// Tab and home-screen icons follow the accent (generated by scripts/export-brand.js); teal is the default.
const ICONS={"teal":["favicon-1490ad8249.png","apple-touch-icon-1490ad8249.png"],"blue":["favicon-blue-32-d35aadcbec.png","apple-touch-icon-blue-d35aadcbec.png"],"indigo":["favicon-indigo-32-b7e876e8bf.png","apple-touch-icon-indigo-b7e876e8bf.png"],"orange":["favicon-orange-32-06d0c1277a.png","apple-touch-icon-orange-06d0c1277a.png"],"pink":["favicon-pink-32-9f8092d71d.png","apple-touch-icon-pink-9f8092d71d.png"]};//icons
window.dnSetIcons=accent=>{const set=ICONS[accent]||ICONS.teal;if(!set)return;const icon=document.querySelector('link[rel="icon"]'),touch=document.querySelector('link[rel="apple-touch-icon"]');if(icon)icon.href='/brand/'+set[0];if(touch)touch.href='/brand/'+set[1]};
// Apply a saved preference before styles/React paint; CSP allows this local script.
try {
 const saved=localStorage.getItem('docknest-theme'),preference=['light','dark','system'].includes(saved)?saved:'light';
 const theme=preference==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):preference;
 const savedAccent=localStorage.getItem('docknest-accent'),accent=['teal','blue','indigo','orange','pink'].includes(savedAccent)?savedAccent:'teal';
 document.documentElement.dataset.preference=preference;
 document.documentElement.dataset.theme=theme;
 document.documentElement.dataset.accent=accent; window.dnSetIcons(accent);
 // Browser chrome colour until the app sets it from the tokens: the accent solid step (light) or the dark surface.
 const solid={teal:'#0D786C',blue:'#006CBF',indigo:'#3D61D9',orange:'#B24D0F',pink:'#B83789'};
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#18191B':solid[accent]);
} catch { document.documentElement.dataset.theme='light';document.documentElement.dataset.preference='light';document.documentElement.dataset.accent='teal'; }
